# Dated principal claim, unaccepted proposal and actual settlement for the same owner.
rol_portfolio<-function(case,origin,lgd){
 bookings<-Filter(function(b)b$first_draw_at=='2024-12-31',case$bookings);positions<-entities<-pds<-list()
 for(b in bookings){row<-Filter(function(r)r$application$application_id==b$application_id,origin$applications)[[1]];cid<-row$application$customer_id;entities[[length(entities)+1L]]<-list(entity_id=cid);positions[[length(positions)+1L]]<-list(position_id=b$facility_id,claim_id=paste0(b$facility_id,'-principal-claim'),facility_id=b$facility_id,entity_id=cid,ead=1000,facility_ead=1000,currency='EUR',sector='sole_trader',region='synthetic-region',exposure_basis='GROSS',collateral_treatment='NONE',household_id=paste0(cid,'-household'));pds[[b$facility_id]]<-row$risk$pd}
 rule<-list(policy_id='separate-sole-traders',version='1',edge_types=list('LEGAL_IDENTITY'),direction_policy='mutual_only',transitive=TRUE);graph<-build_entity_graph(entities,list(),rule,as_of='2024-12-31',known_at='2024-12-31');contract<-list(portfolio_id='owner-origin-book',version='1',currency='EUR',as_of='2024-12-31',known_at='2024-12-31',horizon=30,time_unit='days',probability_measure='PHYSICAL',conditioning='initially_performing',event='first_default')
 prepared<-prepare_credit_portfolio(positions,graph,rule,contract)$value;groups<-unlist(prepared$default_group_ids);gp<-list();for(r in prepared$positions)gp[[r$default_group_id]]<-pds[[r$position_id]];uniforms<-list();weights<-numeric()
 for(a in 0:1)for(b in 0:1){bits<-c(a,b);u<-vapply(seq_along(groups),function(i)if(bits[i]==1)gp[[groups[i]]]/2 else(1+gp[[groups[i]]])/2,0.);uniforms[[length(uniforms)+1L]]<-as.list(u);weights<-c(weights,prod(vapply(seq_along(groups),function(i)if(bits[i]==1)gp[[groups[i]]]else 1-gp[[groups[i]]],0.)))}
 ids<-as.list(paste0('state-',seq_along(weights)-1L));dep<-list(kind='SUPPLIED_DEPENDENT_UNIFORMS',group_ids=as.list(groups));draws<-list(scenario_ids=ids,weights=as.list(weights),group_ids=as.list(groups),sampling_design='EXACT_STATES',group_uniforms=uniforms);paths<-list(scenario_ids=ids,position_ids=lapply(prepared$positions,function(r)r$position_id),driver_hash=content_fingerprint(list(dependence_contract=dep,shared_innovations=draws))$value,ead=lapply(ids,function(i)list(1000,1000)),lgd=lapply(ids,function(i)list(lgd,lgd)),guarantee_treatment='NOT_YET_APPLIED')
 simulation<-simulate_credit_portfolio(prepared,gp,dep,draws,paths,levels=.95)$value;distribution<-credit_loss_distribution(unlist(simulation$portfolio_loss_paths),weights,scenario_ids=unlist(ids),levels=.95,currency='EUR')$value
 list(prepared=prepared,group_pds=gp,simulation=simulation,distribution=distribution,dependence_assumption='Independent distinct owners conditional on supplied covariates; no ownership edge between different businesses',exclusions='Immature account first funded2025-01-31 excluded from2024-12-31 book')
}
rol_benchmark<-function(case,origin,cutoff){
 old<-origin$fitted;training<-old$training_rows;target<-list(event='default',horizon=30,time_unit='days',probability_measure='PHYSICAL',conditioning='performing');fit<-fit_binary_glm(matrix(numeric(),nrow=length(training),ncol=0),vapply(training,function(r)r$outcome,0.),feature_order=character(),link='logit',fit_intercept=TRUE,target=target,training=old$model$training,model_id='owner-intercept-reference',model_version='1');pd<-predict_pd(fit,matrix(numeric(),nrow=1,ncol=0),feature_order=character(),expected_target=target)$value[[1]]
 mt<-origin$monitoring$cohort$target_contract;cohorts<-list();events<-lapply(case$defaults,function(e)list(event_id=e$event_id,entity_id=e$facility_id,event='default',event_at=e$default_at,known_at=e$known_at,default_definition=mt$default_definition));events<-c(events,lapply(case$exits,function(e)list(event_id=e$event_id,entity_id=e$facility_id,event='exit',event_at=e$exit_at,known_at=e$known_at,default_definition=mt$default_definition)));coverage<-lapply(case$bookings,function(b)list(entity_id=b$facility_id,complete_through=b$followup_end,known_at=b$outcome_available_at))
 for(mid in c('reference','candidate','post_review')){model<-if(mid=='reference')fit$model else old$model;forecasts<-lapply(case$bookings,function(b){r<-Filter(function(r)r$application$application_id==b$application_id,origin$applications)[[1]];list(forecast_id=paste0(mid,'-',b$facility_id),case_id=b$application_id,entity_id=b$facility_id,cluster_id=r$application$customer_id,cohort='owner-book',segment='owner',model_id=mid,model_version='1',forecast_at=b$first_draw_at,known_at=b$first_draw_at,pd=if(mid=='reference')pd else r$risk$pd,target=mt,prediction_origin='HOLDOUT')});bundle<-build_monitoring_cohorts(forecasts,events,coverage,target_contract=mt,evaluation_cutoff=cutoff)$value;cohorts[[mid]]<-list(cohort=bundle,model_version='1',parameter_version='1',model_fingerprint=content_fingerprint(model)$value,training_known_at=model$training$known_at)}
 design<-list(model_id='reference',model_version='1',parameter_version='1',data_fingerprint=content_fingerprint(case)$value,population_id='owner-first-funded',split_id='live-heldout',prediction_origin='HOLDOUT',evaluation_cutoff=cutoff,target=target)
 result<-benchmark_predictions(cohorts[c('reference','candidate')],reference_model_id='reference',metrics='brier',matching_policy='strict',multiple_comparisons='none',design=design,uncertainty='none')$value
 overrides<-override_monitoring(cohorts$candidate,cohorts$post_review,list(),policy=list(approved_authorities=list('committee'),reference='No actual PD override in this owner cohort',concentration_threshold=.6),design=design,metrics='brier',uncertainty='none')$value
 stopifnot(abs(result$metrics$paired_differences$candidate$brier$difference+.109375)<1e-10,overrides$metrics$override_rate==0)
 list(reference_model=fit$model,cohorts=cohorts,design=design,result=result,overrides=overrides)
}
run_retail_owner_lifecycle<-function(case,origin,cutoff,verify_reference=TRUE){
 x<-case$lifecycle;aid<-x$account_id;key<-x$application_id;app<-Filter(function(a)a$application$application_id==key,origin$applications)[[1]];booking<-Filter(function(b)b$application_id==key,case$bookings)[[1]];default<-Filter(function(e)e$facility_id==aid,case$defaults)[[1]];closed<-Filter(function(e)e$facility_id==aid,case$exits)[[1]];resolution<-x$resolution
 if(resolution$known_at>cutoff||resolution$resolution_date!=closed$exit_at||resolution$principal_received+resolution$principal_written_off+resolution$claim_remaining!=x$opening_principal)stop('Actual closure requires a reconciled dated settlement')
 economics<-Filter(function(e)e$application_id==key,case$realized_economics)[[1]];if(economics$principal_cash!=resolution$principal_received)stop('Policy and workout principal ledgers differ')
 if(x$proposal_date>=default$default_at||x$proposal_status!='OFFERED_NOT_ACCEPTED')stop('This scenario requires an unaccepted prior proposal')
 arrears<-Filter(function(r)r$account_id==aid,origin$performing$payment_history)[[1]];if(x$arrangement$contract$principal_arrears!=arrears$dpd$past_due_amount)stop('Proposal arrears differ from actual unpaid principal')
 args<-x$arrangement;for(k in c('discount_factors','period_end_dates'))args[[k]]<-unlist(args[[k]]);for(k in c('baseline','candidate'))for(f in c('payments','period_interest_rates','new_fees','servicing_costs','receipt_fractions'))args[[k]][[f]]<-unlist(args[[k]][[f]]);args$affordability_paths<-lapply(args$affordability_paths,function(r){r$available_cash<-unlist(r$available_cash);r});proposal<-do.call(simulate_repayment_arrangement,args)$value
 schedule<-exposure_schedule(contract=list(facility_id=aid,currency='EUR',as_of=booking$first_draw_at,drawn_principal=x$opening_principal,credit_limit=x$opening_principal,accrued_interest=0),events=list(),annual_interest_rates=0,period_end_dates=default$default_at,day_count='ACT/365F',default_timing='AFTER_PERIOD_END_EVENTS',allow_overlimit=FALSE,currency='EUR')
 ead<-predict_ead(schedule,NULL,feature_order=character(),expected_target=NULL,reference_dates=list(booking$first_draw_at),default_dates=list(default$default_at),currency='EUR')$value
 discounted<-discount_recoveries(x$cashflows,x$discount_curve,x$fx_contract,default_date=default$default_at,evaluation_cutoff=cutoff,reporting_currency='EUR');loss<-workout_lgd(ead$conditional_ead[[1]],discounted,episode_status='CLOSED',default_date=default$default_at,evaluation_cutoff=cutoff,currency='EUR')$value
 linked<-build_recovery_episodes(list(list(episode_id=paste0(aid,'-default'),entity_id=aid,default_at=default$default_at,known_at=default$known_at,ead=1000,currency='EUR')),lapply(x$cashflows,function(f)list(cashflow_id=f$cashflow_id,episode_id=f$episode_id,cashflow_at=f$cashflow_date,known_at=f$known_at,amount=f$amount,kind='recovery',currency=f$currency)),cures=list(),evaluation_cutoff=cutoff)$value
 triples<-list(list('CLEAN',booking$first_draw_at,booking$first_draw_known_at),list('ARREARS','2025-01-15','2025-01-15'),list('DEFAULT',default$default_at,default$known_at),list('CLOSED',closed$exit_at,closed$known_at));states<-lapply(triples,function(z)list(account_id=aid,state_event_id=paste0(aid,'-',z[[1]]),state=z[[1]],occurred_at=z[[2]],known_at=z[[3]]))
 episodes<-build_collections_episodes(states,list(),list(list(account_id=aid,observed_from=booking$first_draw_at,observed_through=cutoff,known_at=cutoff)),list(rule_id='actual-owner-collection',version='1',problem_states=list('ARREARS','DEFAULT'),clean_states=list('CLEAN'),terminal_states=list('CLOSED'),default_states=list('DEFAULT'),probation_days=10,separation_days=15),evaluation_cutoff=cutoff)
 cure<-build_cure_targets(episodes,horizon_days=30,redefault_horizon_days=90,evaluation_cutoff=cutoff)$value;prior<-x$prior_lgd
 if(max(unlist(prior$resolution_dates))>=prior$training$known_at||prior$training$known_at>=booking$first_draw_at)stop('LGD training must be closed and known before live funding')
 lgdfit<-fit_fractional_lgd(matrix(numeric(),nrow=length(prior$values),ncol=0),unlist(prior$values),feature_order=character(),link='logit',covariance='HC0',target=prior$target,training=prior$training,model_id='owner-principal-lgd-prior',model_version='1');lgd<-predict_lgd(lgdfit,matrix(numeric(),nrow=1,ncol=0),feature_order=character(),expected_target=prior$target,default_condition='given_default')$value$mean_lgd[[1]]
 portfolio<-rol_portfolio(case,origin,lgd);audit<-rol_benchmark(case,origin,cutoff)
 horizon_loss<-lifetime_expected_loss(app$risk$pd,1000*lgd,1,30/365,currency='EUR',probability_measure='PHYSICAL')$value;prior_rows<-origin$fitted$training_rows;survival_target<-list(event='default',horizon=30,time_unit='days',probability_measure='PHYSICAL',conditioning='newly_funded_owner');survival<-estimate_survival_curve(rep(0,length(prior_rows)),vapply(prior_rows,function(r)as.numeric(as.Date(if(r$outcome==1)r$default_at else r$outcome_end)-as.Date(r$first_draw_at)),0.),vapply(prior_rows,function(r)r$outcome,0.),weight_policy='frequency',target=survival_target,training=origin$fitted$model$training,model_id='owner-prior-first-default',model_version='1');curves<-predict_event_curves(survival,list(),c(0,17,30),feature_order=character(),target=survival_target)$value;stopifnot(identical(unlist(curves$curves[[1]]$survival),c(1,.5,.5)))
 dependency<-list(list(assessment_id=app$assessment$assessment_id,dependency_type='account',dependency_id=aid));triples<-list(list('PROPOSAL',x$proposal_date,x$proposal_known_at,list(accepted=FALSE,proposal_hash=content_fingerprint(proposal)$value)),list('DEFAULT',default$default_at,default$known_at,list(ever_default=TRUE,ead=ead$conditional_ead[[1]])),list('SETTLEMENT',resolution$resolution_date,resolution$known_at,list(remaining_claim=0,realized_principal_loss=loss$economic_loss)),list('EXIT',closed$exit_at,closed$known_at,list(state='CLOSED',ever_default=TRUE)))
 events<-lapply(seq_along(triples),function(i){z<-triples[[i]];list(event_id=paste0(aid,'-',z[[1]]),idempotency_key=paste0(aid,'-',z[[1]]),occurred_at=z[[2]],known_at=z[[3]],sequence=i-1L,payload=z[[4]],revision_of=NULL)});events<-lapply(events,function(e){e$payload_hash<-content_fingerprint(e$payload)$value;e});events[[length(events)+1L]]<-events[[1]]
 execute<-function(){state<-NULL;seen<-ids<-character();ord<-order(vapply(events,function(e)e$known_at,''),vapply(events,function(e)e$sequence,0.),vapply(events,function(e)e$event_id,''));for(i in ord){e<-events[[i]];if(e$idempotency_key%in%seen)next;seen<-c(seen,e$idempotency_key);ids<-c(ids,e$event_id);state<-apply_assessment_event(state,list(event_id=e$event_id,revision='1',occurred_at=e$occurred_at,known_at=e$known_at,dependencies=list(list(type='account',id=aid)),payload=e$payload),dependency,cutoff)$value$state};list(ids=as.list(ids),state=list(dependencies=state,remaining_claim=resolution$claim_remaining,ever_default=TRUE,state='CLOSED'))}
 first<-execute();second<-execute();snap<-lapply(list(list('MODEL',origin$fitted$model,origin$fitted$model$training$known_at),list('CALIBRATION',origin$fitted$calibrator,origin$fitted$calibrator$metadata$calibration$known_at),list('POLICY',origin$policy,'2024-01-01'),list('SOURCE',x,resolution$known_at)),function(z)list(snapshot_id=z[[1]],kind=z[[1]],content_hash=content_fingerprint(z[[2]])$value,known_at=z[[3]],effective_from=z[[3]],effective_until=NULL));base<-list(checkpoint_id=paste0(aid,'-closed'),as_of=cutoff,known_at=cutoff,event_log_hash=content_fingerprint(events)$value,snapshot_hashes=setNames(lapply(snap,function(s)s$content_hash),vapply(snap,function(s)s$snapshot_id,'')))
 replayargs<-list(event_log=events,original_checkpoints=list(c(base,list(applied_event_ids=first$ids,state=first$state))),replayed_checkpoints=list(c(base,list(applied_event_ids=second$ids,state=second$state,mode='REPLAY'))),snapshot_manifest=snap,replay_contract=list(contract_id=paste0(aid,'-lifecycle-replay'),version='1',reference='Actual separate execution of public event reducer on unaccepted proposal and dated principal settlement',ordering='KNOWN_AT_SEQUENCE_EVENT_ID',idempotency='FIRST_IDENTICAL_DELIVERY',corrections='APPEND_REVISION',required_checkpoint_ids=list(base$checkpoint_id),absolute_tolerance=1e-12,relative_tolerance=0));replay<-do.call(replay_consistency,replayargs)$value
 terminal<-compose_risk_assessment(paste0(aid,'-closed-assessment'),list(subject_id=aid,subject_type='facility'),list(list(component_id='remaining-principal',quantity='EAD',value=0,subject_id=aid,subject_type='facility',variant='remaining_contractual_claim',definition=list(event='default',horizon=30,time_unit='days',probability_measure='PHYSICAL',conditioning='after_documented_full_and_final_settlement'),currency='EUR')),list(profile_id='closed-owner-facility',profile_version='1',model_id='dated-settlement-ledger',model_version='1',model_hash=content_fingerprint(resolution)$value,input_hash=content_fingerprint(x$cashflows)$value),cutoff,cutoff,cutoff)$value
 if(verify_reference)stopifnot(arrears$dpd$dpd==5,ead$conditional_ead[[1]]==1000,loss$economic_loss==400,!proposal$contract_changed,!proposal$default_status_changed,proposal$candidate$remaining_claim==700,abs(lgd-.4)<1e-12,replay$decision$status=='PASS',first$state$ever_default,abs(portfolio$distribution$expected_loss-400)<1e-10)
 list(account_id=aid,application_id=key,cash_scope=x$cash_scope,arrears=arrears,proposal=proposal,ead=ead,linked_recoveries=linked,workout=loss,episodes=episodes$value,cure_targets=cure,lgd_model=lgdfit$model,predicted_lgd=lgd,portfolio=portfolio,benchmark=audit,forecast_horizon_loss=horizon_loss,loss_horizon_scope='First30days only, not full contractual lifetime',prior_event_model=survival$model,prior_event_curve=curves,replay_inputs=replayargs,replay=replay,terminal_assessment=terminal,terminal_state=first$state)
}
